  const ID = (this.ID !== null ? builder.createString(this.ID!) : 0);
  const ELEMENT_SETS = dclObject.createElementSetsVector(builder, builder.createObjectOffsetList(this.ELEMENT_SETS));
  const SKIPPED_REASON = (this.SKIPPED_REASON !== null ? builder.createString(this.SKIPPED_REASON!) : 0);
  const REFUSED = dclObject.createRefusedVector(builder, builder.createObjectOffsetList(this.REFUSED));
