  const FIT = (this.FIT !== null ? this.FIT!.pack(builder) : 0);
  const SAMPLE_TIME_MS = dclObject.createSampleTimeMsVector(builder, this.SAMPLE_TIME_MS);
  const SAMPLE_TEME_STATE = dclObject.createSampleTemeStateVector(builder, this.SAMPLE_TEME_STATE);
  const SAMPLE_LATITUDE_DEG = dclObject.createSampleLatitudeDegVector(builder, this.SAMPLE_LATITUDE_DEG);
  const SAMPLE_LONGITUDE_DEG = dclObject.createSampleLongitudeDegVector(builder, this.SAMPLE_LONGITUDE_DEG);
  const SAMPLE_ALTITUDE_KM = dclObject.createSampleAltitudeKmVector(builder, this.SAMPLE_ALTITUDE_KM);
  const SAMPLE_DENSITY_KG_M3 = dclObject.createSampleDensityKgM3Vector(builder, this.SAMPLE_DENSITY_KG_M3);
  const SAMPLE_DECAY_FACTOR_M2_S = dclObject.createSampleDecayFactorM2SVector(builder, this.SAMPLE_DECAY_FACTOR_M2_S);

  dclObject.startdclObject(builder);
  dclObject.addId(builder, ID);
  dclObject.addElementSets(builder, ELEMENT_SETS);
  dclObject.addBallisticCoefficientM2Kg(builder, this.BALLISTIC_COEFFICIENT_M2_KG);
  dclObject.addSpanS(builder, this.SPAN_S);
  dclObject.addLnBPriorMean(builder, this.LN_B_PRIOR_MEAN);
  dclObject.addLnBPriorSigma(builder, this.LN_B_PRIOR_SIGMA);
