  dclObject.addSetEccentricity(builder, SET_ECCENTRICITY);
  dclObject.addSetCumulativeDecayM(builder, SET_CUMULATIVE_DECAY_M);
  dclObject.addSetResidualM(builder, SET_RESIDUAL_M);
  dclObject.addSetUsed(builder, SET_USED);
  dclObject.addSegmentFromMs(builder, SEGMENT_FROM_MS);
  dclObject.addSegmentToMs(builder, SEGMENT_TO_MS);
  dclObject.addSegmentDecayM(builder, SEGMENT_DECAY_M);
  dclObject.addSegmentMeanAltitudeKm(builder, SEGMENT_MEAN_ALTITUDE_KM);
  dclObject.addMeanAltitudeKm(builder, this.MEAN_ALTITUDE_KM);
